// Parser de Documento de Promociones - Supercines
// Input:  items[0].json.data  (markdown)
// Output: objeto estructurado listo para el agente MUVITO

const raw = $input.first().json.data;

// ---------- Helpers ----------

// Limpia markdown inline: **bold**, *italic*, escapes \. \+ etc.
function clean(text) {
  if (text == null) return '';
  return String(text)
    .replace(/\\([._+\-*])/g, '$1')   // \. \+ \- \_ \* → . + - _ *
    .replace(/\*\*(.+?)\*\*/g, '$1')   // **bold**
    .replace(/\*(.+?)\*/g, '$1')       // *italic*
    .replace(/`([^`]+)`/g, '$1')       // `code`
    .trim();
}

// Parsea un bloque de tabla markdown a array de objetos {col: valor}
function parseTable(block) {
  const lines = block.split('\n')
    .map(l => l.trim())
    .filter(l => l.startsWith('|') && l.endsWith('|'));

  if (lines.length < 2) return [];

  const splitRow = row =>
    row.slice(1, -1).split('|').map(c => clean(c));

  const headers = splitRow(lines[0]);
  // lines[1] es el separador :---- | :---- → lo descartamos
  const dataLines = lines.slice(2);

  return dataLines.map(line => {
    const cells = splitRow(line);
    const obj = {};
    headers.forEach((h, i) => { obj[h] = cells[i] ?? ''; });
    return obj;
  });
}

// Convierte una tabla "Campo | Valor" en un objeto plano
function tableToObject(rows) {
  const obj = {};
  rows.forEach(r => {
    const key = r['Campo'];
    const val = r['Valor'];
    if (key) obj[key] = val;
  });
  return obj;
}

// Extrae el bloque de tabla que sigue inmediatamente después de un encabezado
// dado (regex). Devuelve string con las líneas de tabla, o null.
function extractTableAfter(text, headerRegex) {
  const match = text.match(headerRegex);
  if (!match) return null;

  const after = text.slice(match.index + match[0].length);
  const lines = after.split('\n');
  const tableLines = [];
  let started = false;

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('|') && trimmed.endsWith('|')) {
      tableLines.push(trimmed);
      started = true;
    } else if (started && trimmed === '') {
      // primer línea vacía después de empezar la tabla → fin
      break;
    } else if (started) {
      // línea no-tabla después de iniciar → fin
      break;
    }
    // antes de iniciar, ignoramos líneas vacías y otras
  }

  return tableLines.length ? tableLines.join('\n') : null;
}

// Extrae TODAS las tablas dentro de una sección (entre dos encabezados #)
function extractAllTablesInSection(text, sectionRegex, nextSectionRegex) {
  const start = text.match(sectionRegex);
  if (!start) return [];

  let section = text.slice(start.index + start[0].length);
  if (nextSectionRegex) {
    const end = section.match(nextSectionRegex);
    if (end) section = section.slice(0, end.index);
  }

  // Encontrar bloques de tabla consecutivos
  const lines = section.split('\n');
  const blocks = [];
  let current = [];

  for (const line of lines) {
    const trimmed = line.trim();
    const isTableLine = trimmed.startsWith('|') && trimmed.endsWith('|');
    if (isTableLine) {
      current.push(trimmed);
    } else if (current.length) {
      blocks.push(current.join('\n'));
      current = [];
    }
  }
  if (current.length) blocks.push(current.join('\n'));

  return blocks;
}

// ---------- Parseo ----------

const result = {
  promociones_semanales: [],
  descuentos_permanentes: [],
  cashea: {},
  combos_activos: [],
  instrucciones: [],
};

// 1. Promociones semanales
const tbl1 = extractTableAfter(raw, /#\s*\*?\*?1\\?\.\s*Promociones semanales[^\n]*\*?\*?/i);
if (tbl1) {
  result.promociones_semanales = parseTable(tbl1).map(r => ({
    promocion: r['Promoción'],
    descuento: r['Descuento'],
    condicion: r['Condición'],
  }));
}

// 2. Descuentos permanentes
const tbl2 = extractTableAfter(raw, /#\s*\*?\*?2\\?\.\s*Descuentos permanentes[^\n]*\*?\*?/i);
if (tbl2) {
  result.descuentos_permanentes = parseTable(tbl2).map(r => ({
    categoria: r['Categoría'],
    descuento: r['Descuento'],
    condiciones: r['Condiciones'],
    canal: r['Canal'],
  }));
}

// 3. CASHEA
const tbl3 = extractTableAfter(raw, /#\s*\*?\*?3\\?\.\s*CASHEA\*?\*?/i);
if (tbl3) {
  result.cashea = tableToObject(parseTable(tbl3));
}

// 4. Combos temáticos (puede haber varios + plantilla)
const comboBlocks = extractAllTablesInSection(
  raw,
  /#\s*\*?\*?4\\?\.\s*Combos tem[áa]ticos[^\n]*\*?\*?/i,
  /#\s*\*?\*?5\\?\./i
);

// Detectar plantilla: la tabla cuyo "Nombre del combo" o valores son "—"
for (const block of comboBlocks) {
  const rows = parseTable(block);
  if (!rows.length) continue;
  // Solo procesar tablas Campo|Valor
  if (!('Campo' in rows[0]) || !('Valor' in rows[0])) continue;

  const obj = tableToObject(rows);
  const valores = Object.values(obj).join('').replace(/—/g, '').trim();
  const esPlantilla = valores === '' || valores.toLowerCase().includes('activo / inactivo');
  if (esPlantilla) continue; // descartamos la plantilla vacía

  // Solo incluir combos con Estado = Activo (case-insensitive)
  const estado = (obj['Estado'] || '').toLowerCase();
  if (estado && estado !== 'activo') continue;

  result.combos_activos.push({
    nombre: obj['Nombre Combo'] || obj['Nombre del combo'] || '',
    contenido: obj['Contenido'] || '',
    precio: obj['Precio'] || '',
    version_activa: obj['Versión activa'] || '',
    estado: obj['Estado'] || '',
    nota: obj['Nota'] || '',
  });
}

// 5. Instrucciones (lista con bullets)
const instrMatch = raw.match(/#\s*\*?\*?5\\?\.\s*Instrucciones[^\n]*\*?\*?([\s\S]*)/i);
if (instrMatch) {
  const instrSection = instrMatch[1];
  const bulletLines = instrSection.split('\n')
    .map(l => l.trim())
    .filter(l => l.startsWith('* '));

  result.instrucciones = bulletLines.map(l => clean(l.slice(2)));
}

// ---------- Resumen en texto plano (útil para inyectar al prompt del agente) ----------

const lines = [];
lines.push('=== PROMOCIONES SEMANALES ===');
result.promociones_semanales.forEach(p => {
  lines.push(`- ${p.promocion} | ${p.descuento} | ${p.condicion}`);
});

lines.push('\n=== DESCUENTOS PERMANENTES ===');
result.descuentos_permanentes.forEach(d => {
  lines.push(`- ${d.categoria} | ${d.descuento} | ${d.condiciones} | Canal: ${d.canal}`);
});

lines.push('\n=== CASHEA ===');
Object.entries(result.cashea).forEach(([k, v]) => lines.push(`- ${k}: ${v}`));

lines.push('\n=== COMBOS ACTIVOS ===');
result.combos_activos.forEach(c => {
  lines.push(`- ${c.nombre}`);
  lines.push(`  Contenido: ${c.contenido}`);
  lines.push(`  Precio: ${c.precio}`);
  lines.push(`  Versión activa: ${c.version_activa}`);
  if (c.nota) lines.push(`  Nota: ${c.nota}`);
});

result.resumen_texto = lines.join('\n');

return [{ json: result }];
